def parse_settings(text):
    settings = {}
    for segment in text.split(";"):
        if "=" not in segment:
            continue
        key, value = segment.split("=", 1)
        key, value = key.strip(), value.strip()
        if value.isdigit():
            value = int(value)
        elif value.lower() in ("true", "false"):
            value = value.lower() == "true"
        settings[key] = value
    return settings
